csui.define('csui/controls/tablesettings/menu.item.views/table.settings.menu.group.view',[
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'nuc/lib/marionette',
  'csui/controls/tablesettings/menu.item.views/table.settings.menu.select.view',
  'smart/utils/otwc.loader',
  'hbs!csui/controls/tablesettings/menu.item.views/impl/table.settings.menu.item',
], function (_, Backbone, Marionette, TableSettingsMenuSelectView, otwcLoader, template) {
  'use strict';
  const TableSettingsMenuGroupView = Marionette.CollectionView.extend({
    childView: TableSettingsMenuSelectView,
    template: template,
    tagName: 'otc-menugroup',

    constructor: function TableSettingsMenuGroupView(options) {
      // check mandatory parameters
      if (!options) {
        throw new Error('options object is mandatory for TableSettingsMenuGroupView');
      }
      if (!options.model) {
        throw new Error('options object.model is mandatory for TableSettingsMenuGroupView');
      }

      Marionette.CollectionView.prototype.constructor.call(this, options);

      const items = options.model.get('itemValue');
      this.collection = new Backbone.Collection(items);
      this.listenTo(options.model, 'change', () => {
        // itemValue is an array of toolItem models that belong to this menu group
        this.collection.reset(options.model.get('itemValue'));
      });
    },

    childEvents: {
      'change:selection': 'onChangeSelection', // triggered by otc-menuradio when changing the selection
    },

    onChangeSelection: function (itemView, eventData) {
      this.trigger('change:selection', {selectionView: itemView, itemValue: eventData.itemValue});
    },

  });
  return TableSettingsMenuGroupView;
});
