csui.define('csui/controls/table/impl/column.menu/toolbaritems',[
  'csui/lib/underscore',
  'i18n!csui/controls/table/impl/nls/lang',
  'csui/controls/toolbar/toolitems.factory',
  'csui/controls/table/impl/column.menu/state.toolitem.view',
  'i18n',
  'smart/themes/carbonfiber/ot-icons/icons_smart_action'
], function (_, lang,
  ToolItemsFactory,
  StateToolItemView,
  i18n) {
  'use strict';

  // Keep the keys in sync with csui/widgets/nodestable/toolbaritems.masks
  var toolbarItems = {
    tableColumnToolbar: new ToolItemsFactory({
      sort: [
        {
          signature: "TableColumnSortAscending",
          name: lang.TableColumnMenuSortAscending,
          iconNameForOn: 'csui_smart_utility_checkmark16',
          icon: 'icon',
          dropdown: { renderIconAndText: true },
          customView: true,
          commandData: {
            customView: StateToolItemView
          }
        },
        {
          signature: "TableColumnSortDescending",
          name: lang.TableColumnMenuSortDescending,
          iconNameForOn: 'csui_smart_utility_checkmark16',
          icon: 'icon',
          dropdown: { renderIconAndText: true },
          customView: true,
          commandData: {
            customView: StateToolItemView
          }
        }
      ],
      resize: [
        {
          signature: "TableColumnResizeMinWidth",
          name: lang.TableColumnMenuResizeMinWidth
        },
        {
          signature: "TableColumnResizeFitToContent",
          name: lang.TableColumnMenuFitToContent
        }
      ]
    },
    {
      maxItemsShown: 0, // force toolbar to immediately start with a drop-down list
      dropDownIconName: "csui_action_more32"
    })
  };

  toolbarItems.clone = function () {
    return ToolItemsFactory.cloneToolbarItems(this);
  };

  return toolbarItems;
});
