csui.define('csui/controls/table/table.columns',["csui/lib/backbone", 'i18n!csui/controls/table/impl/nls/lang', 'i18n!csui/models/impl/nls/lang'],
  function (Backbone, lang, modelLang) {

  var TableColumnModel = Backbone.Model.extend({

    idAttribute: "key",

    defaults: {
      key: null,  // key from the resource definitions
      sequence: 0 // smaller number moves the column to the front
    }

  });

  var TableColumnCollection = Backbone.Collection.extend({

    model: TableColumnModel,
    comparator: "sequence",

    getColumnKeys: function () {
      return this.pluck('key');
    },

    deepClone: function () {
      return new TableColumnCollection(
          this.map(function (column) {
            return column.attributes;
          }));
    }

  });

  // columns delivered from server get sequence set to 500

  var tableColumns = new TableColumnCollection([
    {
      key: '_select',
      sequence: 1,
      noTitleInHeader: true,
      title: lang.selectionColumnTitle,
      /* customization is used only when tableColumnsWrappingOn=false */
      customization_resizeable: false,
      customization_width: 32,
      customization_pinned: true,
   },
   {
    key: 'order',
    sequence: 2,
    permanentColumn: true, // don't wrap column due to responsiveness into details row

    /* customization is used only when tableColumnsWrappingOn=false */
    customization_width: 75,
    customization_pinned: true,
    },
    {
      key: 'type',
      sequence: 3,
      titleIconInHeader: 'mime_type',
      permanentColumn: true, // don't wrap column due to responsiveness into details row

      /* customization is used only when tableColumnsWrappingOn=false */
      customization_resizeable: false,
      customization_width: 42,
      customization_pinned: true,
    },
    {
      key: 'name',
      sequence: 4,
      permanentColumn: true, // don't wrap column due to responsiveness into details row
      isNaming: true,  // use this column as a starting point for the inline forms

      /* customization is used only when tableColumnsWrappingOn=false */
      customization_resize_span: 'reserved', // resize all columns from 'name' to 'reserved' as one column.
      customization_min_width: 168,
      customization_width: 500,
      customization_pinned: true,
    },
    {
      key: 'reserved',
      sequence: 5,
      title: modelLang.state, // "reserved" is just to bind the column to some property
      noTitleInHeader: true, // don't display a visible text in the column header

      /* customization is used only when tableColumnsWrappingOn=false */
      customization_resizeable: false,
      customization_pinned: true,
    },
    {
      key: 'size',
      sequence: null, // null means only use column if definitions_order and type comes from server.
      customization_min_width: 80
    },
    {
      key: 'description',
      sequence: 890,
      is_default_column: false,
    },
    {
      key: 'wnd_comments',
      sequence: 900,
      noTitleInHeader: true,
      permanentColumn: true, // don't wrap column due to responsiveness into details row

      /* customization is used only when tableColumnsWrappingOn=false */
      customization_resizeable: false,
    },
    {
      key: 'favorite',
      sequence: 910,
      noTitleInHeader: true,
      permanentColumn: true, // don't wrap column due to responsiveness into details row

      /* customization is used only when tableColumnsWrappingOn=false */
      customization_resizeable: false,
    }
  ]);

  return tableColumns;

});
